import bisect

def f(arr, c):
	n = len(arr)
	total = 0
	start = []
	for i in range(n):
		start.append(arr[i] + (i + 1))
		arr[i] += min(i + 1, n - i)
	sorted_arr = sorted(arr)
	pref = [sorted_arr[0]]
	for i in range(1, n):
		pref.append(pref[-1] + sorted_arr[i])
	for i in range(n):
		if c - start[i] >= 0:
			index = bisect.bisect_left(pref, c - start[i])
			if index >= n:
				index -= 1
			if pref[index] > c - start[i]:
				index -= 1
			if index == -1:
				total = max(total, 1)
				continue
			if sorted_arr[index] >= arr[i]:
				index = index = bisect.bisect_left(pref, c - (start[i] - arr[i]))
				if index >= n:
					index -= 1
				if pref[index] > c - (start[i] - arr[i]):
					index -= 1
				cur = index + 1
			else:
				cur = index + 2
			total = max(total, cur)
	return total
k = int(input())
res = []
while k > 0:
	nc = input().split(' ')
	(n, c) = (int(nc[0]), int(nc[1]))
	temp = input().split(' ')
	arr = []
	for num in temp:
		arr.append(int(num))
	res.append(f(arr, c))
	k -= 1
